    proof! { admit(); }
    let pde: PageDirectoryEntry = unsafe { pd.read(pde_idx) }.ok_or_else(|| {
        let reason: &str = "invalid PDE read from kernel PD";
        #[cfg(not(verus_keep_ghost))]
